-- Real, professional ai_summary feature bullets for curated tools. Safe to re-run.
update public.tools t set ai_summary = v.summary, updated_at = now()
from (values

  ('chatgpt', '["Answers questions and writes or edits text in any style","Writes, explains, and debugs code across languages","Analyzes uploaded files and images, and can browse the web"]'::jsonb),
  ('claude', '["Handles very long documents and context with ease","Strong at careful reasoning, analysis, and long-form writing","Writes and refactors code with a focus on safe, helpful answers"]'::jsonb),
  ('gemini', '["Multimodal across text, images, audio, and code","Built into Google Search, Workspace, and Android","Free tier plus advanced models via Google One"]'::jsonb),
  ('perplexity', '["Answers with live web results and inline citations","Follow-up threads keep your research in context","Pro Search and Focus modes for deeper, sourced answers"]'::jsonb),
  ('midjourney', '["Generates high-quality, stylized images from text","Fine style control with parameters and reference images","Ideal for concept art, illustration, and mood boards"]'::jsonb),
  ('stability-ai', '["Open Stable Diffusion image models you can self-host","Hosted API for text-to-image generation","Models spanning image, video, and audio"]'::jsonb),
  ('leonardo-ai', '["Generates images, textures, and game assets","Fine-grained control with presets and custom models","Fast in-browser canvas and editing tools"]'::jsonb),
  ('ideogram', '["Renders legible, accurate text inside images","Great for posters, logos, and social graphics","Style presets and prompt enhancement"]'::jsonb),
  ('krea', '["Real-time image generation you steer live","Enhance and upscale existing images","Turn rough sketches into finished art"]'::jsonb),
  ('runway', '["Generate video from text or images","AI editing: green screen, inpainting, motion tracking","Popular for VFX and social content"]'::jsonb),
  ('pika', '["Create short videos from text or images","Effects for motion, lip-sync, and scene extension","Fast, browser-based generation"]'::jsonb),
  ('luma', '["Generates realistic, fluid video clips","Works from text prompts or still images","From Luma Labs, known for 3D capture"]'::jsonb),
  ('synthesia', '["Studio-style videos with lifelike AI avatars","Voiceovers in 140+ languages","Great for training and marketing videos"]'::jsonb),
  ('heygen', '["Avatar videos from a script in minutes","Translate and lip-sync existing footage","Custom avatars and voices"]'::jsonb),
  ('descript', '["Edit audio and video by editing the transcript","One-click filler-word and silence removal","AI voices and studio-quality sound"]'::jsonb),
  ('capcut', '["Fast editor with AI captions and effects","Background removal and auto-templates","Built for short-form social video"]'::jsonb),
  ('elevenlabs', '["Natural text-to-speech in hundreds of voices","Voice cloning and multilingual dubbing","APIs for apps, narration, and games"]'::jsonb),
  ('suno', '["Generate complete songs from a prompt","Adds vocals and instruments automatically","Great for demos, jingles, and fun"]'::jsonb),
  ('udio', '["High-fidelity music generation with vocals","Extend and remix generated tracks","Prompt for genre, mood, and lyrics"]'::jsonb),
  ('cursor', '["AI code editor built on VS Code","Edits across files and understands your codebase","Chat, autocomplete, and multi-file changes"]'::jsonb),
  ('github-copilot', '["Inline code suggestions as you type","Chat to explain, fix, and write code","Works across popular IDEs"]'::jsonb),
  ('v0', '["Generate React and Tailwind UI from a prompt","Iterate from images or screenshots","Copy production-ready components"]'::jsonb),
  ('bolt', '["Prompt a full-stack web app into existence","Run, edit, and deploy in the browser","No local setup required"]'::jsonb),
  ('replit', '["Cloud IDE with an AI agent that builds apps","Instant hosting and deployment","Real-time collaboration"]'::jsonb),
  ('hugging-face', '["Hub for open models, datasets, and demos","Libraries and hosted inference","Center of the open-source ML community"]'::jsonb),
  ('notion-ai', '["Drafts, summarizes, and edits inside your notes","Answers questions across your workspace","Built into Notion docs and databases"]'::jsonb),
  ('grammarly', '["Checks grammar, clarity, and tone everywhere","Generative drafting and rewriting","Works in browsers, desktop, and mobile"]'::jsonb),
  ('jasper', '["On-brand marketing copy and campaigns","Brand voice controls and templates","Built for marketing teams"]'::jsonb),
  ('copy-ai', '["Drafts marketing and sales copy","Runs go-to-market workflows","Templates for every channel"]'::jsonb),
  ('deepl', '["High-accuracy translation across languages","AI writing help for tone and phrasing","Apps for desktop, mobile, and web"]'::jsonb),
  ('gamma', '["Generate decks, docs, and sites from a prompt","Clean templates with one-click restyle","Present or publish instantly"]'::jsonb),
  ('canva', '["All-in-one design with Magic Studio AI","AI image generation and background removal","Thousands of ready-made templates"]'::jsonb),
  ('figma', '["Industry-standard UI and UX design tool","AI for first drafts and content","Real-time multiplayer collaboration"]'::jsonb),
  ('framer', '["Design and ship responsive websites","Generate pages, copy, and layouts with AI","Publish with one click"]'::jsonb),
  ('otter', '["Records and transcribes meetings live","Automatic summaries and action items","Searchable notes across every call"]'::jsonb),
  ('fireflies', '["AI notetaker that joins your meetings","Transcribes and summarizes automatically","Syncs notes to your tools"]'::jsonb),
  ('zapier', '["Automate work across 7000+ apps","AI agents and steps, no code needed","Multi-step workflows and triggers"]'::jsonb),
  ('n8n', '["Open-source workflow automation","Build AI agents and pipelines","Self-host or run in the cloud"]'::jsonb),
  ('character-ai', '["Create and chat with AI characters","Roleplay, practice, and companionship","Customizable personalities"]'::jsonb),
  ('mistral', '["Efficient open-weight language models","Le Chat assistant and developer API","European AI built on open models"]'::jsonb)
) as v(slug, summary)
where t.slug = v.slug;
